def get_segments(hs, positions):
    for i, h in enumerate(hs):
        j = positions[h]
        positions[h] += 1
        if i > j:
            i, j = j, i
        yield i, j


def merge_segments(segments):
    ci, cj = None, None
    for i, j in sorted(segments):
        if ci is None:
            ci, cj = i, j
        elif i > cj:
            yield ci, cj
            ci, cj = i, j
        else:
            cj = max(cj, j)
    yield ci, cj


def max_partition(n, hs):
    seq = sorted(hs)
    positions = {seq[i]:i for i in range(n)
                 if not (i > 0 and seq[i-1] == seq[i])}

    return sum(1 for _ in merge_segments(get_segments(hs, positions)))


