def solve():
    n, m = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u - 1, v - 1))

    def are_adjacent(char1, char2):
        if char1 == char2:
            return True
        if (char1 == 'a' and char2 == 'b') or (char1 == 'b' and char2 == 'a'):
            return True
        if (char1 == 'b' and char2 == 'c') or (char1 == 'c' and char2 == 'b'):
            return True
        return False

    def generate_graph_from_string(s):
        adj_matrix = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                if are_adjacent(s[i], s[j]):
                    adj_matrix[i][j] = True
                    adj_matrix[j][i] = True
        return adj_matrix

    def compare_graphs(graph1, graph2):
        for i in range(n):
            for j in range(n):
                if graph1[i][j] != graph2[i][j]:
                    return False
        return True

    def edges_to_adj_matrix(edges, n):
        adj_matrix = [[False] * n for _ in range(n)]
        for u, v in edges:
            adj_matrix[u][v] = True
            adj_matrix[v][u] = True
        return adj_matrix

    input_adj_matrix = edges_to_adj_matrix(edges, n)

    import itertools
    for s_tuple in itertools.product(['a', 'b', 'c'], repeat=n):
        s = "".join(s_tuple)
        generated_adj_matrix = generate_graph_from_string(s)

        if compare_graphs(generated_adj_matrix, input_adj_matrix):
            print("Yes")
            print(s)
            return

    print("No")

