def solve():
    n = int(input())
    fragments = []
    for _ in range(n):
        fragments.append(input())

    all_chars = set()
    for fragment in fragments:
        all_chars.update(list(fragment))
    all_chars = sorted(list(all_chars))

    precedence = {}
    for char in all_chars:
        precedence[char] = set()

    for fragment in fragments:
        for i in range(len(fragment) - 1):
            precedence[fragment[i]].add(fragment[i+1])

    def topological_sort():
        result = ""
        visited = set()
        temp_stack = set()

        def dfs(char):
            if char in temp_stack:
                return False  # Cycle detected
            if char in visited:
                return True

            visited.add(char)
            temp_stack.add(char)

            for next_char in precedence[char]:
                if not dfs(next_char):
                    return False

            temp_stack.remove(char)
            nonlocal result
            result = char + result
            return True

        for char in sorted(all_chars):
            if char not in visited:
                if not dfs(char):
                    return ""  # Cycle detected

        return result

    print(topological_sort())

