        m = bisect(l, (lo + hi) // 2)
        mid = l[m]
        a, b = mid - lo, hi - mid
        if a < b:
            a = b
        mid = l[m - 1]
        b, c = mid - lo, hi - mid
        if b < c:
            b = c
        if a > b:
            a = b
        if n > a:
            n = a
    print(n)


