def solve():
    n, k = map(int, input().split())
    universities = list(map(int, input().split()))
    edges = []
    for _ in range(n - 1):
        u, v = map(int, input().split())
        edges.append((u, v))

    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def count_universities(start_node, excluded_edge=None):
        count = 0
        visited = [False] * (n + 1)
        stack = [start_node]
        visited[start_node] = True

        while stack:
            node = stack.pop()
            if node in universities:
                count += 1

            for neighbor in adj[node]:
                if not visited[neighbor]:
                    if excluded_edge is None or (node, neighbor) != excluded_edge and (neighbor, node) != excluded_edge:
                        visited[neighbor] = True
                        stack.append(neighbor)
        return count

    total_distance = 0
    for u, v in edges:
        count_u = count_universities(u, (u, v))

        total_distance += min(count_u, 2 * k -count_u)

    print(total_distance)

solve()

