    zero_edges = []

    for _ in range(m):
        u, v, w = map(int, input().split())
        edges.append((u, v, w))
        adj[u].append((v, w))
        adj[v].append((u, w))
        if w == 0:
            zero_edges.append((u, v))

    # Assign initial weight of 1 to zero-weight edges
    for i in range(len(edges)):
        if edges[i][2] == 0:
            edges[i] = (edges[i][0], edges[i][1], 1)

    for u in range(n):
