    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    def dijkstra(start, end, graph, current_edges):
        dist = {node: float('inf') for node in range(n)}
        dist[start] = 0
        pq = [(0, start)]

