```python
def solve():
    n, m = map(int, input().split())
    d = list(map(int, input().split()))
    a = list(map(int, input().split()))

    def possible(days):
        last_days = d[:days]
        passed = [False] * m

        exam_days = [0] * (m+1)
        for i in range (days):
            exam_days[d[i]] += 1

        for i in range(m):
            exam_days[i+1] = 0

        for i in range(days-1, -1, -1):
            if last_days[i] != 0 and not passed[last_days[i]-1]:
                passed[last_days[i]-1] = True
                exam_days[last_days[i]] = 1

        for i in range (1,m+1):
            if exam_days[i] == 0:
                continue 
            passed_once = False
            for k in range (days):
                if d[k] == i:
                    passed_once = True
                    break
            if not passed_once:
                return False

        if not all(passed):
            return False

        needed_preparation = sum(a)
        available_preparation = 0
        for i in range (days):
            if d[i] == 0:
                 available_preparation += 1
            elif exam_days[d[i]] == 0:
                available_preparation+=1

        if needed_preparation > available_preparation:
            return False
        return True

    left, right = 1, n
    ans = -1
    while left <= right:
        mid = (left + right) // 2
        if possible(mid):
            ans = mid
            right = mid - 1
        else:
            left = mid + 1

    print(ans)

