class Solution:
    def solve(self, n, a, edges):
        c = [[] for _ in range(n + 1)]
        w = [0] * (n + 1)
        for p, weight in edges:
            c[p].append(len(c) -1)
            w[len(c) - 1] = weight

        ans = [0] * (n + 1)

        def dfs(v, parent, dist_from_root):
            count = 0
            for u in c[v]:
                if u != parent:
                    new_dist = dist_from_root + w[u]
                    if new_dist <= a[u]:
                        count += 1
                    count += dfs(u, v, new_dist)
            ans[v] = count
            return count

        dfs(1, 0, 0)
        return ans[1:]


