def solve():
    n, m, k = map(int, input().split())

    def check(x):
        total_pillows = x

        # Left side
        if x >= k:
            total_pillows += k * x - k * (k - 1) // 2 - k
        else:
            total_pillows += (k - x) * (x + k + 1) // 2 - (k - x)

        # Right side
        if x >= n - k + 1:
            total_pillows += (n - k + 1) * x - (n - k + 1) * (n - k) // 2 - (n-k+1)
        else:
            total_pillows += (n - k - x + 1) * (x + n - k + 2) // 2 - (n-k-x+1)

        total_pillows += n
        total_pillows -= x

        return total_pillows <= m

    low = 1
    high = m
    ans = 0
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    print(ans)

