def solve(length, modulus, sequence):
    if length == 0:
        return 0, 1
    if length == 1:
        return sequence[0], 1

    initial_difference = (sequence[1] - sequence[0]) % modulus
    if initial_difference < 0:
        initial_difference += modulus

    sequence_set = set(sequence)

    count = 0
    for value in sequence:
        count += ((value + initial_difference) % modulus) in sequence_set

    count = length - count

    if count == 0:
        return -1, -1  # No common difference found

    common_difference = (initial_difference * pow(count, modulus - 2, modulus)) % modulus

    first_element = sequence[0]
    while (first_element + modulus - common_difference) % modulus in sequence_set:
        first_element = (first_element + modulus - common_difference) % modulus

    for i in range(length):
        if (first_element + i * common_difference) % modulus not in sequence_set:
            return -1, -1

    return first_element, common_difference


