def solve():
    n, m = map(int, input().split())
    names = [input() for _ in range(n)]

    adj = [[1] * n for _ in range(n)]
    for _ in range(m):
        name1, name2 = input().split()
        i = names.index(name1)
        j = names.index(name2)
        adj[i][j] = 0
        adj[j][i] = 0

    max_clique = []

    for mask in range(2**n):
        subset = []
        for i in range(n):
            if (mask >> i) & 1:
                subset.append(i)

        is_clique = True
        for i in range(len(subset)):
            for j in range(i + 1, len(subset)):
