    n1, n2, k1, k2 = map(int, input().split())
    dp = [[[[0] * 2 for _ in range(max(k1, k2) + 1)] for _ in range(n2 + 1)] for _ in range(n1 + 1)]
    dp[0][0][0][0] = 1

