import itertools

def is_lucky(n):
  s = str(n)
  for digit in s:
    if digit != '4' and digit != '7':
      return False
  return True

def solve():
  n, k = map(int, input().split())

  if n <= 12 and math.factorial(n) < k:
      print("-1")
      return

  m = 0
  fact = 1
  while fact < k:
    m += 1
    if n - m <= 12:
      fact = math.factorial(m)
    else :
      fact *= (m+1)

  if n - m < 0:
    print("-1")
    return

  remaining = list(range(n - m + 1, n + 1))


  if m <= 0 and k!=1:
      print("-1")
      return

  if m > 0:

      perms = list(itertools.permutations(remaining))

      if len(perms) < k:
          print("-1")
          return

      perm = perms[k - 1]
  else:
