def solve():
    n, m = map(int, input().split())
    adj = [[] for _ in range(n + 1)]
    students = set(range(1, n + 1))

    for _ in range(m):
        a, b = map(int, input().split())
        adj[a].append(b)
        adj[b].append(a)

    kicked_groups = 0
    while True:
        to_kick = set()
        for student in students:
            if len(adj[student]) == 1:
                to_kick.add(student)

        if not to_kick:
