                adj[student] = []

        new_adj = [[] for _ in range(n + 1)]
        for i in range(1,n+1):
            if i in students:
                for neighbor in adj[i]:
                    if neighbor in students:
                        new_adj[i].append(neighbor)
        adj = new_adj


    print(kicked_groups)

solve()
