def extract_vowel_suffix(s, k):
    vowels = "aeiou"
    vowel_count = 0
    for i in range(len(s) - 1, -1, -1):
        if s[i] in vowels:
            vowel_count += 1
            if vowel_count == k:
                return s[i:]
    return ""

def determine_quatrain_rhyme_scheme(lines, k):
    suffixes = [extract_vowel_suffix(line, k) for line in lines]
    if all(suffixes[0] == s for s in suffixes):
        return "aaaa"
    elif suffixes[0] == suffixes[1] and suffixes[2] == suffixes[3]:
        return "aabb"
    elif suffixes[0] == suffixes[2] and suffixes[1] == suffixes[3]:
        return "abab"
    elif suffixes[0] == suffixes[3] and suffixes[1] == suffixes[2]:
        return "abba"
    else:
        return "NO"

