    visited = set()
    visited.add((0, 0, 0))

    while q:
        wall, height, time = q.popleft()

        # Check if ninja escaped
        if height + k >= n or height + 1 >= n:
            print("YES")
            return

        # Move up
        new_height_up = height + 1
        if new_height_up < n:
