            start_computer = computers[start_task_index]

            completed_tasks = set()
            completed_tasks.add(start_task_index + 1)  # Task numbers are 1-indexed

            current_computer = start_computer
            total_hours = 1

            while len(completed_tasks) < n:

                while True:
                    initial_completed_count = len(completed_tasks)

                    for task_index in tasks_by_computer[current_computer]:
                        if task_index + 1 in completed_tasks:
