from collections import deque

def solve():
    n = int(input())
    computers = list(map(int, input().split()))
    computers = [c - 1 for c in computers]
    dependencies = [[] for _ in range(n)]
    in_degree = [0] * n

    for i in range(n):
        line = list(map(int, input().split()))
        num_dependencies = line[0]
        in_degree[i] = num_dependencies
        for j in range(1, len(line)):
            dependencies[line[j] - 1].append(i)

    def calculate_time(start_computer):
        time = 0
        current_computer = start_computer
        in_degree_copy = in_degree[:]

        task_queues = [deque() for _ in range(3)]
        for i in range(n):
            if computers[i] == 0 and in_degree_copy[i] == 0:
                task_queues[0].append(i)
            elif computers[i] == 1 and in_degree_copy[i] == 0:
                task_queues[1].append(i)
            elif computers[i] == 2 and in_degree_copy[i] == 0:
                task_queues[2].append(i)

        completed_tasks = 0
        while completed_tasks < n:
            if task_queues[current_computer]:
                task = task_queues[current_computer].popleft()
                time += 1
                completed_tasks += 1

                for dependent_task in dependencies[task]:
                    in_degree_copy[dependent_task] -= 1
                    if in_degree_copy[dependent_task] == 0:
                        task_queues[computers[dependent_task]].append(dependent_task)
            else:
                time += 1
                current_computer = (current_computer + 1) % 3
        return time

    min_time = float('inf')
    for start_computer in range(3):
        min_time = min(min_time, calculate_time(start_computer))
    print(min_time)

