def solve():
    n, m, x, y = map(int, input().split())
    grid = [input() for _ in range(n)]
    cols = list(zip(*grid))

    white_counts = [col.count('.') for col in cols]
    black_counts = [n - w for w in white_counts]

    dp = {} 

    def calculate_cost(index, last_color, current_length):
        if index == m:
            if x <= current_length <= y or current_length == 0:
                return 0
            else:
                return float('inf')

        if (index, last_color, current_length) in dp:
            return dp[(index, last_color, current_length)]

        ans = float('inf')

        # Option 1: Continue the current color
        if current_length < y:
            if last_color == 'white' or last_color is None:
                ans = min(ans, white_counts[index] + calculate_cost(index + 1, 'white', current_length + 1))
            if last_color == 'black' or last_color is None:
                ans = min(ans, black_counts[index] + calculate_cost(index + 1, 'black', current_length + 1))

        # Option 2: Start a new color (if current length is valid)
        if x <= current_length <= y or current_length == 0:
            ans = min(ans, black_counts[index] + calculate_cost(index + 1, 'black', 1))
            ans = min(ans, white_counts[index] + calculate_cost(index + 1, 'white', 1))

        dp[(index, last_color, current_length)] = ans
        return ans

    print(calculate_cost(0, None, 0))

