def solve():
    s = input()
    counts = {}

    def is_valid_date(d, m, y):
        if not (2013 <= y <= 2015):
            return False
        if not (1 <= m <= 12):
            return False

        days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

        if not (1 <= d <= days_in_month[m]):
            return False

