                    if date_str in counts:
                        counts[date_str] += 1
                    else:
                        counts[date_str] = 1
            except ValueError:
                pass

    best_date = None
    max_count = 0

    for date, count in counts.items():
        if count > max_count:
            max_count = count
            best_date = date

    print(best_date)

