    def find_smallest(index, remaining_divisors, current_number):
        nonlocal min_num
        if remaining_divisors == 1:
            min_num = min(min_num, current_number)
            return

        if current_number > 10**18:
            return

        if index >= len(primes):
            return 


        for exponent in range(1, remaining_divisors + 1):
            if remaining_divisors % exponent == 0:
                new_number = current_number
                power = exponent - 1

                if power > 0:
                  if (10**18) // (new_number) < primes[index]**power:
                    continue
                  new_number *= primes[index]**power


                find_smallest(index + 1, remaining_divisors // exponent, new_number)

