def solve():
    n = int(input())
    titles = [input() for _ in range(n)]

    def is_substring(s, title):
        return s in title

    def is_original(s, titles):
        for title in titles:
            if is_substring(s, title):
                return False
        return True

    def generate_strings(length):
        import itertools
        for s in itertools.product('abcdefghijklmnopqrstuvwxyz', repeat=length):
            yield "".join(s)

    length = 1
    while True:
        for s in generate_strings(length):
            if is_original(s, titles):
                print(s)
                return
        length += 1

