    result = "ab"
    n -= 2
    while n > 0:
        result += result[-1]
        if result[-1] == 'a':
            result += 'b'
        else:
            result += 'a'
        n -= 1

    distinct_chars = 2
    current_char = 'c'
    while distinct_chars < k:
