      continue
    if rook_attacks(rook_a, current_king, [king_white]):
      #print('rook A attacks %d, %d' % (r, c))
      continue
    if rook_attacks(rook_b, current_king, [king_white]):
      #print('rook B attacks %d, %d' % (r, c))
      continue
    #print('%d, %d is safe' % (r, c))
    finish('OTHER')

finish('CHECKMATE')

