limit = events[0].end
for event in events:
  limit = max(limit, event.end)

current_events = set()

for i in range(n):
  if len(current_events) == 0:
    pos = limit + 1
    for event in events:
      if event.pick == None and event.start < pos:
        pos = event.start
  for event in events:
    if event.pick == None and event.start == pos:
      current_events.add(event)
