            for i in range(x - 1, -1, -1):
                rotated_row += piece[i][j]
            rotated_piece.append(rotated_row)
        return rotated_piece

    def rotate_180(piece):
      rotated = []
      for row in piece[::-1]:
        rotated.append(row[::-1])
      return rotated

    def rotate_270(piece):
        rotated_90 = rotate_piece(piece)
        return rotate_180(rotated_90)

