    def get_side(x, y):
        if y == 0 and 0 <= x <= n:
            return 1
        elif x == n and 0 <= y <= n:
            return 2
        elif y == n and 0 <= x <= n:
            return 3
        elif x == 0 and 0 <= y <= n:
            return 4
        else:
            return -1  # Should never happen

    side1 = get_side(x1, y1)
    side2 = get_side(x2, y2)

    def perimeter_distance(side, x, y, n):
        if side == 1:
            return x
        elif side == 2:
            return n + y
        elif side == 3:
            return 2 * n + (n - x)
        elif side == 4:
            return 3 * n + (n - y)
        else:
            return -1 

    dist1 = perimeter_distance(side1, x1, y1, n)
    dist2 = perimeter_distance(side2, x2, y2, n)

    diff = abs(dist1 - dist2)
    print(min(diff, 4 * n - diff))

