def dist(p1, p2):
    return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2

def solve():
    xs, ys = map(int, input().split())
    n = int(input())
    objects = []
    for _ in range(n):
        objects.append(tuple(map(int, input().split())))

    handbag = (xs, ys)

    dp = {}
    pre = {}

    def get_dp(mask, last):
        if (mask, last) not in dp:
            dp[mask, last] = float('inf')
        return dp[mask, last]

    def get_pre(mask, last):
        if (mask, last) not in pre:
            pre[mask, last] = None
        return pre[mask, last]


    dp[0, 0] = 0
    pre[0, 0] = None

    for mask in range(1 << n):
        for last in range(n + 1):
            if (mask, last) not in dp:
                continue

            if dp[mask, last] == float('inf'):
                continue

            # Pick one item
            for i in range(1, n + 1):

                if (mask & (1 << (i-1))) == 0:

                    new_mask = mask | (1 << (i-1))
                    d = dist(objects[last-1] if last != 0 else handbag,
                             objects[i-1])
                    if get_dp(new_mask, i) > dp[mask, last] + d :
                      dp[new_mask, i] = dp[mask, last] + d
                      pre[new_mask, i] = (mask, last)


            # Pick two items from the handbag
            if last == 0:
                for i in range(1, n + 1):
                    if (mask & (1 << (i - 1))) == 0:
                        for j in range(1, n + 1):
                            if i != j and (mask & (1 << (j - 1))) == 0:
                                new_mask = mask | (1 << (i - 1)) | (1 << (j - 1))

                                d1 = dist(handbag, objects[i - 1])
                                d2 = dist(objects[i - 1], objects[j - 1])

                                if get_dp(new_mask, j) > dp[mask, last] + d1+d2:
                                  dp[new_mask, j] = dp[mask, last] + d1 + d2
                                  pre[new_mask, j] = (mask, 0)

                                d1 = dist(handbag, objects[j - 1])
                                d2 = dist(objects[j-1], objects[i - 1])

                                if get_dp(new_mask, i) > dp[mask, last] + d1+d2:
                                  dp[new_mask, i] = dp[mask, last] + d1+d2
                                  pre[new_mask, i] = (mask, 0)

    min_cost = float('inf')
    end_node = -1
    for i in range(1, n + 1):
        d = dist(objects[i-1], handbag)
        if get_dp((1 << n) - 1, i) + d < min_cost:
            min_cost = get_dp((1 << n) - 1, i) + d
            end_node = i

    print(int(min_cost))

    path = []
    curr_mask = (1 << n) - 1
    curr_node = end_node

    while True:
        path.append(curr_node)
        prev_state = get_pre(curr_mask, curr_node)
        if prev_state is None:
            break
        curr_mask, curr_node = prev_state
    path.append(0)


    path.reverse()
    print(*path)

solve()
