def generate_lucky_numbers(digits):
    if digits == 0:
        return [""]
    smaller_numbers = generate_lucky_numbers(digits - 1)
    numbers = []
    for number in smaller_numbers:
        numbers.append(number + "4")
        numbers.append(number + "7")
    return numbers

def is_super_lucky(number):
    four_count = number.count('4')
    seven_count = number.count('7')
    return four_count == seven_count

def find_smallest_super_lucky(n):
    n_str = str(n)
    length = len(n_str)
    if length % 2 != 0:
        length += 1

    all_super_lucky_numbers = []
    for i in range(length // 2 + 1):
        lucky_numbers = generate_lucky_numbers(length)

        super_lucky_numbers = [int(num) for num in lucky_numbers if is_super_lucky(num)]
        all_super_lucky_numbers.extend(super_lucky_numbers)

    all_super_lucky_numbers = sorted(list(set(all_super_lucky_numbers)))

    for num in all_super_lucky_numbers:
