def solve():
    x, y, p, q = map(int, input().split())

    if p == 0:
        if x == 0:
            return 0
        else:
            return -1
    if p == q:
        if x == y:
            return 0
        else:
            return -1

    low = 0
    high = 10**9
    ans = -1
    while low <= high:
        mid = (low + high) // 2
        if mid * p >= x and mid * q >= y:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    if ans == -1:
        return -1
    else:
        return ans * q - y

