def solve():
    n = int(input())
    c = list(map(int, input().split()))
    s = [''] * n

    def calculate_c(string):
        calculated_c = [0] * n
        for i in range(n):
            for length in range(1, n - i + 1):
                substring = string[i:i+length]
                if len(set(substring)) == 1:
                    calculated_c[length-1] += 1
        return calculated_c

    def is_valid(current_string):
