def solve():
    n = int(input())
    teams = []
    for _ in range(n):
        teams.append(input().split())

    short_names = []
    for team, city in teams:
        short_names.append(team[:3])

    for i in range(n):
        for j in range(i + 1, n):
            if short_names[i] == short_names[j]:
                # Conflict! Try to resolve
                team_i, city_i = teams[i]
                team_j, city_j = teams[j]

                short_name_i_alt = team_i[:2] + city_i[0]
                short_name_j_alt = team_j[:2] + city_j[0]

                can_switch_i = True
                can_switch_j = True

                #Is the alternate short name currently assigned?
                for k in range(n):
                    if k != i and short_names[k] == short_name_i_alt:
                      can_switch_i = False
                      break

                for k in range(n):
                     if k != j and short_names[k] == short_name_j_alt:
                       can_switch_j = False
                       break

                #If we switch someone, someone can't use the 3-letter version
                for k in range(n):
                    if k != i and teams[k][0][:3] == short_names[i] and i != k and short_names[i] == teams[k][0][:3]:
                      can_switch_i = False
                      break

                for k in range(n):
                    if k != j and teams[k][0][:3] == short_names[j] and j != k and short_names[j] == teams[k][0][:3]:
                      can_switch_j = False
                      break

                if can_switch_i:

                    short_names[i] = short_name_i_alt

                elif can_switch_j:

                    short_names[j] = short_name_j_alt


                else:
                    print("NO")                    
                    return



    used = set()
    for name in short_names:
        if name in used:
          print("NO")
          return
        used.add(name)


    print("YES")
    for name in short_names:
        print(name)

