def solve():
    n = int(input())
    teams = []
    for _ in range(n):
        teams.append(input().split())

    assignments = {}
    short_names = []

    for team, city in teams:
        assignments[(team, city)] = team[:3]
        short_names.append(team[:3])

    duplicates = set()
    counts = {}
    for name in short_names:
        if name not in counts:
            counts[name] = 0
        counts[name] += 1
        if counts[name] > 1:
            duplicates.add(name)

    final_assignments = {}
    used_names = set()

    changed = True
    while changed:
        changed = False
        used = set()
        for team, city in teams:
            name = assignments[(team, city)]
            if name in used:
                duplicates.add(name)
            used.add(name)

        for team, city in teams:
            if (team, city) in final_assignments:
                continue

            name = assignments[(team, city)]
            if name in duplicates:
                alt_name = team[:2] + city[:1]
                if alt_name not in used_names:
                    assignments[(team, city)] = alt_name
                    final_assignments[(team, city)] = alt_name
                    used_names.add(alt_name)
                    changed = True
                else:
                    final_assignments[(team, city)] = name
                    used_names.add(name)


            else:
                final_assignments[(team, city)] = name
                used_names.add(name)

    used = set()
    for team, city in teams:
        name = assignments[(team, city)]
        if name in used:
            print("NO")
            return

        used.add(name)

    print("YES")
    for team, city in teams:
        print(assignments[(team, city)])
solve()
