def solve():
    n = int(input())
    a, b, c, d = map(int, input().split())
    parents = [0] + list(map(int, input().split()))

    adj = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        adj[parents[i-1]].append(i)
        adj[i].append(parents[i-1])

    def is_leaf(node):
        return len(adj[node]) == 1 and node != 1

    def subtree_size(node, parent):
        count = 1
        for neighbor in adj[node]:
            if neighbor != parent:
                count += subtree_size(neighbor, node)
        return count

    size_a = subtree_size(a, parents[a-1] if a > 1 else 0)
    size_b = subtree_size(b, parents[b-1] if b > 1 else 0)
    size_c = subtree_size(c, parents[c-1] if c > 1 else 0)
    size_d = subtree_size(d, parents[d-1] if d > 1 else 0)

    if is_leaf(a):
        size_a -= 1
    if is_leaf(b):
        size_b -= 1
    if is_leaf(c):
        size_c -= 1
    if is_leaf(d):
        size_d -= 1

    if size_a == size_b and size_c == size_d:
        print("YES")
    else:
        print("NO")

