        a.append(ai)
        b.append(bi)

    def is_possible(t):
        required_power = 0
        for i in range(n):
            required_power += max(0, a[i] * t - b[i])
        return required_power <= p * t

    low = 0
    high = 10**9

    all_safe = True
    for i in range(n):
      if a[i] > 0:
