def solve():
    k = int(input())
    s = input()
    words = s.split()

    def check(width):
        lines = 1
        current_length = 0
        for word_index in range(len(words)):
            word = words[word_index]
            parts = word.split('-')
            for i in range(len(parts)):
                part = parts[i]
                if len(part) > width:
                    return False
                if current_length == 0:
                    current_length += len(part)
                else:
                    if current_length + len(part) + 1 <= width:
                        current_length += len(part) + 1
