def solve():
    n = int(input())
    events = []
    for _ in range(n):
        events.append(input().split())

    dp = {}
    for i in range(n + 1):
        for j in range(-1, 2001):
            dp[(i, j)] = -1

    dp[(0, -1)] = 0

    for i in range(1, n + 1):
        event_type = events[i-1][0]
        x = int(events[i-1][1])

        if event_type == "win":
            # Option 1: Keep the memory stick
            for k in range(-1, 2001):
                if dp[(i-1, k)] != -1:
                    dp[(i, x)] = max(dp[(i, x)], dp[(i-1, k)])

            # Option 2: Discard the memory stick
            for k in range(-1, 2001):
                 if dp[(i-1, k)] != -1:
                    dp[(i, -1)] = max(dp[(i, -1)], dp[(i-1, k)])
        else: # event_type == "sell"
            # Option 1: Sell the memory stick if we have it
            if dp[(i-1, x)] != -1:
                dp[(i, -1)] = dp[(i-1, x)] + (1 << x)

            # Option 2: Otherwise, keep whatever we have
            for k in range(-1, 2001):
                if k != x and dp[(i-1, k)] != -1:
                    dp[(i, k)] = max(dp[(i,k)], dp[(i-1, k)])
                elif k == -1 and dp[(i-1, k)] != -1:
                    dp[(i,k)] = max(dp[(i,k)], dp[(i-1, k)])
            if dp[(i,-1)] == -1:
                if i > 1:
                    if (event_type == "sell" and int(events[i-2][1]) == x and events[i-2][0] == "sell"):#handle the first sell
                        dp[(i,-1)] = -1
                    else:
                        dp[(i,-1)] = -1




    max_earnings = 0
    for k in range(-1, 2001):
        max_earnings = max(max_earnings, dp[(n, k)])

    print(max_earnings)

solve()
