    max_liking = float('-inf')

    import itertools

    for assignment in itertools.product([0, 1, 2], repeat=7):
        team0 = [i for i, team in enumerate(assignment) if team == 0]
        team1 = [i for i, team in enumerate(assignment) if team == 1]
        team2 = [i for i, team in enumerate(assignment) if team == 2]

