        for hero in team1:
            experiences[hero] = b // len(team1)
        for hero in team2:
            experiences[hero] = c // len(team2)

        diff = max(experiences) - min(experiences)

        liking = 0
        for team in [team0, team1, team2]:
            for i in range(len(team)):
                for j in range(len(team)):
