def func(l,n,m,row,col):
    for i in range(n):
        mi=min(l[i])
        if mi:  
            l[i]= [x-mi for x in l[i]]
            for j in range(mi):
                row.append(i)
    for j in range(m):
        c= [x[j] for x in l]
        mi = min(c)
        if max(c)-mi>0:
            print("-1")
            exit()
        for i in range(mi):
            col.append(j)

R= lambda: map(int,input().split())
n, m= R()
l,row, col,l2= [], [], [], []
for _ in range(n):
    l.append(list(R()))
if n>m:
    for j in range(m):
        l2.append([x[j] for x in l])
    func(l2,m,n,col,row)
else:   func(l,n,m,row,col)
print(len(row)+len(col))
for i in row:   print("row ",i+1)
for i in col:   print("col", i+1)

