def solve():
    n, m = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, input().split())))

    def check(row_first):
        g = [row[:] for row in grid]
        rows = [0] * n
        cols = [0] * m
        moves = []

        if row_first:
            for i in range(n):
                rows[i] = min(g[i])
                for j in range(m):
                    g[i][j] -= rows[i]

            for j in range(m):
                cols[j] = max(g[i][j] for i in range(n))

            for i in range(n):
                for j in range(m):
                    g[i][j] -= cols[j]
                    if g[i][j] != 0:
                        return -1, []
        else:
            for j in range(m):
                cols[j] = min(g[i][j] for i in range(n))
                for i in range(n):
                    g[i][j] -= cols[j]
            for i in range(n):
                rows[i] = max(g[i][j] for j in range(m))

            for i in range(n):
                for j in range(m):
                    g[i][j] -= rows[i]
                    if g[i][j] != 0:
                        return -1, []

        for i in range(n):
            for _ in range(rows[i]):
                moves.append(f"row {i+1}")
        for j in range(m):
            for _ in range(cols[j]):
                moves.append(f"col {j+1}")

        return len(moves), moves

    ans1, moves1 = check(True)
    ans2, moves2 = check(False)

    if ans1 == -1 and ans2 == -1:
        print(-1)
        return

    if ans1 == -1:
        print(ans2)
        for move in moves2:
            print(move)
        return

    if ans2 == -1:
        print(ans1)
        for move in moves1:
            print(move)
        return


    if ans1 <= ans2:
        print(ans1)
        for move in moves1:
            print(move)
    else:
        print(ans2)
        for move in moves2:
            print(move)

solve()
