def solve(grid, num_rows, num_cols, row_ops, col_ops):
    for i in range(num_rows):
        min_val = min(grid[i])
        if min_val:  
            grid[i]= [x-min_val for x in grid[i]]
            for j in range(min_val):
                row_ops.append(i)
    for j in range(num_cols):
        column = [grid[x][j] for x in range(num_rows)]
        min_val = min(column)
        if max(column)-min_val>0:
            print("-1")
            exit()
        for i in range(min_val):
            col_ops.append(j)

